// V segment (trait)
trait VDJ { fn bind(&self, antigen: &Key) -> bool; }
// D segment (generic diversity)
struct Gate<K: VDJ> { key: K }
// J segment (impl = joining)
impl VDJ for Ed25519Key {
    fn bind(&self, antigen: &Key) -> bool {
        self.verify(antigen) // the antigen fits or it doesn't
    }
}
